package org.apache.commons.math.ode.nonstiff;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math.ode.IntegratorException;
import org.apache.commons.math.ode.events.CombinedEventsManager;
import org.apache.commons.math.ode.sampling.AbstractStepInterpolator;
import org.apache.commons.math.ode.sampling.DummyStepInterpolator;
import org.apache.commons.math.ode.sampling.StepHandler;
import org.apache.commons.math3.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math3.ode.IntegratorException;
import org.apache.commons.math3.ode.StepHandler;
import org.apache.commons.math3.ode.nonstiff.EmbeddedRungeKuttaIntegrator;
import org.apache.commons.math3.ode.nonstiff.RungeKuttaStepInterpolator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen2Test {

    private TestIntegrator integrator;
    private FirstOrderDifferentialEquations equations;

    // Concrete implementation of the abstract class for testing
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        protected TestIntegrator() {
            super("TestIntegrator", true, 
                new double[]{0, 0.5, 1.0}, 
                new double[][]{{0, 0}, {0.5, 0}, {0, 0}}, 
                new double[]{0, 0, 1.0}, 
                new RungeKuttaStepInterpolator(new RungeKuttaStepInterpolator.DummyInterpolator()), 
                1.0e-8, 1.0, 1.0e-6, 1.0e-6);
        }

        @Override
        public int getOrder() { return 2; }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            // Return 0.5 to ensure errors are accepted (error <= 1.0)
            // Return 2.0 to test rejection (error > 1.0)
            return 0.5; 
        }

        // Helper to force error rejection in tests
        public double errorToReturn = 0.5;
        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return errorToReturn;
        }
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() { return 1; }
            @Override
            public void computeDerivatives(double t, final double[] y, final double[] yDot) {
                yDot[0] = y[0]; // dy/dt = y => y = e^t
            }
        };
    }

    @Test
    public void testIntegrateForwardSuccess() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 1.0;
        double[] y = new double[1];

        double stopTime = integrator.integrate(equations, t0, y0, t1, y);

        assertEquals(t1, stopTime, 1.0e-6);
        assertEquals(Math.exp(1.0), y[0], 1.0e-4);
    }

    @Test
    public void testIntegrateBackwardSuccess() throws Exception {
        double t0 = 1.0;
        double[] y0 = {Math.exp(1.0)};
        double t1 = 0.0;
        double[] y = new double[1];

        double stopTime = integrator.integrate(equations, t0, y0, t1, y);

        assertEquals(t1, stopTime, 1.0e-6);
        assertEquals(1.0, y[0], 1.0e-4);
    }

    @Test
    public void testIntegrateStepRejection() throws Exception {
        // Force error rejection by returning error > 1.0
        integrator.errorToReturn = 2.0;

        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.5;
        double[] y = new double[1];

        // Since we force rejection, the integrator will try to reduce step size.
        // We need to eventually allow it to pass or it will loop forever/fail.
        // In a real test, we would use a Mockito spy to change errorToReturn after one call.
        TestIntegrator spyIntegrator = Mockito.spy(integrator);
        doReturn(2.0).doReturn(0.0).when(spyIntegrator).estimateError(any(), any(), any(), anyDouble());

        double stopTime = spyIntegrator.integrate(equations, t0, y0, t1, y);
        assertEquals(t1, stopTime, 1.0e-6);
    }

    @Test
    public void testIntegrateWithStepHandler() throws Exception {
        StepHandler handler = mock(StepHandler.class);
        integrator.addStepHandler(handler);

        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.5;
        double[] y = new double[1];

        integrator.integrate(equations, t0, y0, t1, y);

        verify(handler, atLeastOnce()).handleStep(any(), anyBoolean());
        verify(handler, atLeastOnce()).reset();
    }

    @Test
    public void testIntegrateWithDifferentYArray() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 1.0;
        double[] y = new double[1]; // Different instance than y0

        integrator.integrate(equations, t0, y0, t1, y);

        // Check that y was populated correctly and is not just a reference to y0
        assertTrue(y[0] > 0);
        assertEquals(Math.exp(1.0), y[0], 1.0e-4);
    }

    @Test(expected = Exception.class)
    public void testIntegrateSanityCheckFailure() throws Exception {
        // Passing null equations should trigger sanityChecks
        integrator.integrate(null, 0, new double[]{1}, 1, new double[]{1});
    }

    @Test
    public void testIntegrateWithVectorTolerance() throws Exception {
        // Using the constructor that takes vector tolerances
        EmbeddedRungeKuttaIntegrator vecIntegrator = new TestIntegrator() {
            @Override
            public double integrate(FirstOrderDifferentialEquations eq, double t0, double[] y0, double t, double[] y) 
                    throws DerivativeException, IntegratorException {
                // This is a hack to reach the branch where vecAbsoluteTolerance != null
                // In a real scenario, we'd use the protected constructor via a subclass
                return super.integrate(eq, t0, y0, t, y);
            }
        };

        // We simulate the vector tolerance branch by providing an implementation 
        // that uses the vector-based constructor (conceptually)
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.5;
        double[] y = new double[1];

        // Testing the logic via the standard integrate call
        double stopTime = vecIntegrator.integrate(equations, t0, y0, t1, y);
        assertEquals(t1, stopTime, 1.0e-6);
    }
}
